import { jsonSchemaToZod } from "json-schema-to-zod";
import { z } from "zod";
const schemas = z.record(
  z.string().regex(/^[a-z][A-Za-z0-9]*Schema$/),
  z.object({
    direction: z.enum(["request", "response"]),
    schema: z.record(z.string(), z.unknown()),
  }),
);
export function renderGeometrySchemas(input: unknown): string {
  const bodies = schemas.parse(input);
  return (
    '// Generated by pnpm generate:geometry. Do not edit.\nimport { z } from "zod";\n' +
    Object.entries(bodies)
      .map(([name, { direction, schema }]) => {
        const code = jsonSchemaToZod(schema, { name, module: "esm", noImport: true });
        if (/\bz\.any\s*\(/.test(code))
          throw new Error(`${name}: unsupported schema emits z.any()`);
        const type = name.charAt(0).toUpperCase() + name.slice(1).replace(/Schema$/, "");
        return `${code}\nexport type ${type} = z.${direction === "request" ? "input" : "output"}<typeof ${name}>;\n`;
      })
      .join("\n") +
    `\nexport const geometryBodySchemas = { ${Object.keys(bodies).join(", ")} };\n`
  );
}
